def clamp(x, lo, hi):
    if lo > hi:
        lo, hi = hi, lo
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

reference_tests:
def test_inside():
    assert clamp(5, 0, 10) == 5

def test_below():
    assert clamp(-3, 0, 10) == 0

def test_above():
    assert clamp(99, 0, 10) == 10

def test_on_low_bound():
    assert clamp(0, 0, 10) == 0

def test_on_high_bound():
    assert clamp(10, 0, 10) == 10

def test_swapped_bounds():
    assert clamp(5, 10, 0) == 5
    assert clamp(-1, 10, 0) == 0
